import itertools

target_total = 100
budget = 50.0
item_prices = [0.50, 3.00, 10.50]

def find_valid_combination():
    # Iterate over possible numbers of each item type
    for x in range(1, target_total):
        for y in range(1, target_total - x + 1):
            z = target_total - x - y
            if z > 0:
                # Calculate total cost
                total_cost = x * item_prices[0] + y * item_prices[1] + z * item_prices[2]
                if abs(total_cost - budget) < 1e-6:
                    return {'x': x, 'y': y, 'z': z}
    return None

result = find_valid_combination()
if result:
    print('Valid combination found:', result)
else:
    print('No valid combination found.')
